import {spawn} from 'node:child_process';import {readFile,writeFile,copyFile,mkdir} from 'node:fs/promises';import path from 'node:path';
const root=process.cwd(),port=4349,token='synthetic-demo-build-token-2026',data=path.join(root,'examples/demo-project');await mkdir(data,{recursive:true});
const env={...process.env,PORT:String(port),WB_BASE_URL:`http://127.0.0.1:${port}`,WB_TOKEN:token,WB_DATA_DIR:data};
const server=spawn(process.execPath,['server/index.mjs'],{env,stdio:['ignore','pipe','pipe']});let logs='';server.stdout.on('data',b=>logs+=b);server.stderr.on('data',b=>logs+=b);
try{for(let i=0;i<80;i++){try{if((await fetch(env.WB_BASE_URL+'/health')).ok)break;}catch{}await new Promise(r=>setTimeout(r,100));}const demo=spawn(process.execPath,['scripts/demo.mjs'],{env,stdio:'inherit'});const code=await new Promise(r=>demo.on('exit',r));if(code!==0)throw Error('Demo script failed');const metadata=JSON.parse(await readFile('evidence/demo.json'));const response=await fetch(env.WB_BASE_URL+metadata.export.url,{headers:{authorization:'Bearer '+token}});if(!response.ok)throw Error('Download failed');await mkdir('deliverables',{recursive:true});await writeFile('deliverables/stanley-maltese-synthetic-10s.mp4',Buffer.from(await response.arrayBuffer()));console.log('Demo generated and copied.');}finally{server.kill('SIGTERM');await new Promise(r=>server.on('exit',r));await writeFile('evidence/demo-build.log',logs);}
